{"path": "/app/decompress.py", "content": "#!/usr/bin/env python3
import argparse
import json
from pathlib import Path
import struct
from typing import Iterator, Tuple

TYPE_DIR = 0
TYPE_FILE = 1

DIR_HEADER_SIZE = 1 + 4
FILE_HEADER_SIZE = 1 + 4 + 8 + 8 + 4


def iter_bundle_paths(data_root: Path, depth: int) -> Iterator[Path]:
    if depth == 1:
        for bundle in sorted(data_root.glob("bundle_*.bin")):
            yield bundle
        return
    pattern = "**/bundle_*.bin"
    for bundle in sorted(data_root.glob(pattern)):
        yield bundle


def read_exact(handle, size: int) -> bytes:
    data = handle.read(size)
    if len(data) != size:
        raise ValueError("Unexpected end of bundle while reading")
    return data


def process_bundle(bundle_path: Path, output_root: Path) -> None:
    with open(bundle_path, "rb") as handle:
        while True:
            type_bytes = handle.read(1)
            if not type_bytes:
                break
            record_type = struct.unpack(">B", type_bytes)[0]
            if record_type == TYPE_DIR:
                path_len = struct.unpack(">I", read_exact(handle, 4))[0]
                path_bytes = read_exact(handle, path_len)
                rel_path = path_bytes.decode("utf-8")
                target_dir = output_root / Path(rel_path)
                target_dir.mkdir(parents=True, exist_ok=True)
            elif record_type == TYPE_FILE:
                path_len = struct.unpack(">I", read_exact(handle, 4))[0]
                path_bytes = read_exact(handle, path_len)
                rel_path = path_bytes.decode("utf-8")
                total_size = struct.unpack(">Q", read_exact(handle, 8))[0]
                offset = struct.unpack(">Q", read_exact(handle, 8))[0]
                data_len = struct.unpack(">I", read_exact(handle, 4))[0]
                data = read_exact(handle, data_len)
                target_path = output_root / Path(rel_path)
                target_path.parent.mkdir(parents=True, exist_ok=True)
                if offset == 0:
                    with open(target_path, "wb") as out:
                        if data:
                            out.write(data)
                        if total_size == 0:
                            out.truncate(0)
                else:
                    with open(target_path, "r+b") as out:
                        out.seek(offset)
                        if data:
                            out.write(data)
            else:
                raise ValueError(f"Unknown record type {record_type}")


def decompress(resharded_dir: Path) -> None:
    manifest_path = resharded_dir / "manifest.json"
    if not manifest_path.exists():
        raise SystemExit(f"Manifest not found at {manifest_path}")
    manifest = json.loads(manifest_path.read_text())
    if manifest.get("format") != "reshard-v1":
        raise SystemExit("Unsupported manifest format")
    data_root = resharded_dir / manifest.get("data_dir", "data")
    if not data_root.exists():
        raise SystemExit(f"Data directory {data_root} not found")
    depth = int(manifest.get("depth", 1))

    output_root = resharded_dir
    for bundle_path in iter_bundle_paths(data_root, depth):
        process_bundle(bundle_path, output_root)


def main() -> None:
    parser = argparse.ArgumentParser(description="Restore a resharded dataset")
    parser.add_argument("resharded_dir", help="Directory created by compress.py")
    args = parser.parse_args()
    resharded_dir = Path(args.resharded_dir).resolve()
    if not resharded_dir.is_dir():
        raise SystemExit(f"Resharded directory {resharded_dir} does not exist")
    decompress(resharded_dir)


if __name__ == "__main__":
    main()
"}

